CREATE TABLE employees (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100),
    salary DECIMAL(10,2)
);

UPDATE employees
SET salary = 60000
WHERE id = 1;

CREATE TABLE orders (
    order_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customers(id)
);

CREATE TABLE student_course (
    student_id INT,
    course_id INT,
    PRIMARY KEY(student_id, course_id)
);

SELECT *
FROM colors
CROSS JOIN sizes;

CREATE VIEW employee_details AS
SELECT id, name, salary
FROM employees;

CREATE FUNCTION square(num INT)
RETURNS INT AS $$
BEGIN
    RETURN num * num;
END;
$$ LANGUAGE plpgsql;

CREATE SEQUENCE employee_seq
START 1
INCREMENT 1;

BEGIN;
UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;
COMMIT;

SELECT *
FROM employees
ORDER BY salary DESC;

SELECT *
FROM employees
LIMIT 10 OFFSET 10;

SELECT name,
COALESCE(bonus, 0) AS bonus
FROM employees;

SELECT name, salary
FROM employees
WHERE salary > (
    SELECT AVG(salary)
    FROM employees
);

SELECT *
FROM employees
WHERE department IN ('HR', 'Sales', 'IT');

SELECT *
FROM employees
WHERE salary > ANY (
    SELECT salary
    FROM managers
);

CREATE TABLE sales (
    sale_date DATE,
    amount NUMERIC
) PARTITION BY RANGE (sale_date);
